/* Maintainer utility; the generated asset ships ready to use without a build. */
const fs=require('node:fs'),path=require('node:path');
const folder=path.join(__dirname,'../assets/water');
const png=fs.readFileSync(path.join(folder,'arctic-sky.png'));
fs.writeFileSync(path.join(folder,'arctic-sky.data.js'),
 "/* Generated byte-identical copy of arctic-sky.png for direct file:// WebGL use. See README.md. */\n"+
 "globalThis.HaloWaterSkyDataURL='data:image/png;base64,"+png.toString('base64')+"';\n");
